    translations: {"it": {"kid": "In calde sorgenti sottomarine, minuscole sostanze chimiche si unirono e fecero qualcosa di straordinario: si copiarono. Erano piccolissime — non più grandi di un granello di polvere — ma furono le prime cose vive!", "fun": "Le prime cellule erano così piccole che miliardi di esse starebbero su un granello di sabbia.", "summary": "La vita probabilmente iniziò in sorgenti idrotermali, dove molecole auto-replicanti formarono le prime cellule.", "deep": ["L'abiogenesi descrive come la vita potrebbe essere sorta da materia non vivente.", "Le prime cellule erano procarioti, semplici e senza nucleo.", "Le prove fossili più antiche risalgono a ~3,5 miliardi di anni fa.", "L'RNA potrebbe essere stata la prima molecola auto-replicante."]}},
    kid: "In warm underwater springs, tiny chemicals got together and started doing something amazing: copying themselves. They were teeny-tiny — no bigger than a single speck of dust — but they were the very first living things!",
